/* ============ Drag-to-reorder (pointer-based, offline, no external libs) ============ */
const TAP_THRESHOLD = 6;   // px of travel before we switch from tap to drag
let drag = null;

function onPointerDown(e){
  if (!e.isPrimary) return;
  if (e.target.closest('button')) return;
  const li = e.target.closest('li.item');
  if (!li || li.dataset.dragging === '1') return;
  const list = li.parentElement;
  if (e.pointerType === 'mouse' || e.pointerType === 'pen'){
    li.setPointerCapture && li.setPointerCapture(e.pointerId);
  }
  drag = {
    li, list, pointerId: e.pointerId,
    startX: e.clientX, startY: e.clientY,
    started: false,
  };
  document.addEventListener('pointermove', onPointerMove, {passive:false});
  document.addEventListener('pointerup', onPointerUp);
  document.addEventListener('pointercancel', onPointerCancel);
}

function onPointerMove(e){
  if (!drag || e.pointerId !== drag.pointerId) return;
  const dx = e.clientX - drag.startX;
  const dy = e.clientY - drag.startY;
  if (!drag.started){
    if (Math.hypot(dx, dy) < TAP_THRESHOLD) return;
    startDrag(e);
  }
  ghostMove(e.clientX, e.clientY);
  movePlaceholder(e.clientY);
  if (e.cancelable) e.preventDefault();
}

function onPointerUp(e){
  if (!drag || e.pointerId !== drag.pointerId) return;
  const wasDrag = drag.started;
  cleanupDrag();
  if (wasDrag) commitDrag();
}
function onPointerCancel(e){
  if (!drag || e.pointerId !== drag.pointerId) return;
  const wasDrag = drag.started;
  cleanupDrag();
  if (wasDrag) commitDrag();
}

function removeListeners(){
  document.removeEventListener('pointermove', onPointerMove);
  document.removeEventListener('pointerup', onPointerUp);
  document.removeEventListener('pointercancel', onPointerCancel);
}

function startDrag(e){
  const li = drag.li;
  const rect = li.getBoundingClientRect();
  const ghost = li.cloneNode(true);
  ghost.classList.add('is-ghost');
  ghost.classList.remove('is-placeholder');
  ghost.removeAttribute('tabindex');
  Object.assign(ghost.style, {
    width: rect.width+'px',
    height: rect.height+'px',
    left: '0', top: '0', margin:'0',
    transform: `translate(${e.clientX - rect.width/2}px, ${e.clientY - rect.height/2}px)`,
  });
  document.body.appendChild(ghost);

  const li2 = e.target.closest('li.item') || li;
  const ph = document.createElement('li');
  ph.className = 'item is-placeholder';
  ph.style.height = rect.height + 'px';
  ph.innerHTML = li2 ? li2.innerHTML : li.innerHTML;
  li.parentNode.insertBefore(ph, li);
  li.remove();
  li.classList.add('is-grabbing');

  drag.started = true;
  drag.ghost = ghost;
  drag.ph = ph;
  drag.li = li2 || li;
  document.body.classList.add('is-dragging');
}

function ghostMove(x,y){
  if (!drag.ghost) return;
  const li = drag.li;
  const w = li.offsetWidth || 200;
  const h = li.offsetHeight || 40;
  drag.ghost.style.transform = `translate(${x - w/2}px, ${y - h/2}px)`;
}

function movePlaceholder(clientY){
  const list = drag.list;
  const items = Array.from(list.children).filter(x => x.className.includes('item') && x !== drag.ph);
  if (!items.length) return;
  let insertBefore = null;
  for (const it of items){
    const r = it.getBoundingClientRect();
    if (clientY < r.top + r.height/2){ insertBefore = it; break; }
  }
  if (insertBefore){ list.insertBefore(drag.ph, insertBefore); }
  else { list.appendChild(drag.ph); }
}

function cleanupDrag(){
  if (!drag) return;
  if (drag.ghost) drag.ghost.remove();
  if (drag.ph) drag.ph.remove();
  drag.li.classList.remove('is-grabbing');
  removeListeners();
  document.body.classList.remove('is-dragging');
  drag = null;
}

function commitDrag(){
  // Reinsert the actual li at the position of the placeholder it replaced.
  // Since we removed the li and placed the ph where the li went, we need to
  // reinsert li in the DOM at the location of the ph slot.
  // But we've already removed ph in cleanupDrag, so we need to track it before cleanup.
}

