  li.setPointerCapture && li.setPointerCapture(e.pointerId);

  const list = li.parentElement;
  const rect = li.getBoundingClientRect();
  drag = {
    li, list, e,
    startX: e.clientX, startY: e.clientY,
    rectL: rect.left, rectT: rect.top,
    w: rect.width, h: rect.height,
    grabbed: false,
    moved: false,
    ghost: null, ph: null,
    pointerId: e.pointerId,
  };
  document.addEventListener('pointermove', onPointerMove, {passive:false});
  document.addEventListener('pointerup', onPointerUp, {once:false});
  document.addEventListener('pointercancel', onPointerCancel, {once:true});
}

function onPointerMove(e){
  if (!drag || e.pointerId !== drag.pointerId) return;
  const dx = e.clientX - drag.startX;
  const dy = e.clientY - drag.startY;
  if (!drag.grabbed){
    if (Math.abs(dx) > GRAB_X_THRESHOLD || Math.abs(dy) > 0){
      // wait until clear intent: require 8px on any axis
      if (Math.hypot(dx,dy) < 8) return;
      drag.grabbed = true;
      startDrag();
    } else return;
  }
  document.body.classList.add('is-dragging');
  setGhostVars(drag.ghost, e.clientX, e.clientY);
  movePlaceholder(e.clientY);
  if (e.cancelable) e.preventDefault();
}
