  if (!drag || e.pointerId !== drag.pointerId) return;
  if (drag.grabbed){
    endDrag(true);
  } else {
    // treat as click (scroll, focus). Do nothing.
  }
  cleanListeners();
  drag = null;
  document.body.classList.remove('is-dragging');
}
function onPointerCancel(e){
  if (!drag || e.pointerId !== drag.pointerId) return;
  if (drag.grabbed) endDrag(false);
  cleanListeners();
  drag = null;
  document.body.classList.remove('is-dragging');
